import{_ as l,a0 as t,w as r,s as o,ao as d,I as p,x as a,a1 as e,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"在 Linux 上压缩文件的 5 种方法 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 上压缩文件的 5 种方法 | LCTT (202005) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 上压缩文件的 5 种方法 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 上压缩文件的 5 种方法 | LCTT (202005) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202005/20200417 How to compress files on Linux 5 ways","title":"在 Linux 上压缩文件的 5 种方法","tag":"202005","desc":""},"relativePath":"202005/20200417 How to compress files on Linux 5 ways.md","filePath":"[post].md"}'),c={name:"202005/20200417 How to compress files on Linux 5 ways.md"};function h(g,s,b,f,k,u){const n=t("Link");return r(),o("div",null,[s[15]||(s[15]=d(`<h1 id="在-linux-上压缩文件的-5-种方法" tabindex="-1">在 Linux 上压缩文件的 5 种方法 <a class="header-anchor" href="#在-linux-上压缩文件的-5-种方法" aria-label="Permalink to “在 Linux 上压缩文件的 5 种方法”">​</a></h1><blockquote><p>在 Linux 系统上有很多可以用于压缩文件的工具，但它们的表现并不都是一样的，也不是所有的压缩效果都是一样的。在这篇文章中，我们比较其中的五个工具。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202005/06/231536tgxma941yb8dgl53.jpg" alt=""></p><p>在 Linux 上有不少用于压缩文件的命令。最新最有效的一个方法是 <code>xz</code>，但是所有的方法都有节省磁盘空间和维护备份文件供以后使用的优点。在这篇文章中，我们将比较这些压缩命令并指出显著的不同。</p><h3 id="tar" tabindex="-1">tar <a class="header-anchor" href="#tar" aria-label="Permalink to “tar”">​</a></h3><p><code>tar</code> 命令不是专门的压缩命令。它通常用于将多个文件拉入一个单个的文件中，以便容易地传输到另一个系统，或者将文件作为一个相关的组进行备份。它也提供压缩的功能，这就很有意义了，附加一个 <code>z</code> 压缩选项能够实现压缩文件。</p><p>当使用 <code>z</code> 选项为 <code>tar</code> 命令附加压缩过程时，<code>tar</code> 使用 <code>gzip</code> 来进行压缩。</p><p>就像压缩一组文件一样，你可以使用 <code>tar</code> 来压缩单个文件，尽管这种操作与直接使用 <code>gzip</code> 相比没有特别的优势。要使用 <code>tar</code> 这样做，只需要使用 <code>tar cfz newtarfile filename</code> 命令来标识要压缩的文件，就像标识一组文件一样，像这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tar cfz bigfile.tgz bigfile</span></span>
<span class="line"><span>            ^            ^</span></span>
<span class="line"><span>            |            |</span></span>
<span class="line"><span>            +- 新的文件  +- 将被压缩的文件</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ ls -l bigfile*</span></span>
<span class="line"><span>-rw-rw-r-- 1 shs shs 103270400 Apr 16 16:09 bigfile</span></span>
<span class="line"><span>-rw-rw-r-- 1 shs shs 21608325 Apr 16 16:08 bigfile.tgz</span></span></code></pre></div><p>注意，文件的大小显著减少了。</p><p>如果你愿意，你可以使用 <code>tar.gz</code> 扩展名，这可能会使文件的特征更加明显，但是大多数的 Linux 用户将很可能会意识到与 <code>tgz</code> 的意思是一样的 – <code>tar</code> 和 <code>gz</code> 的组合来显示文件是一个压缩的 tar 文件。在压缩完成后，你将同时得到原始文件和压缩文件。</p><p>要将很多文件收集在一起并在一个命令中压缩出 “tar ball”，使用相同的语法，但要指定要包含的文件为一组，而不是单个文件。这里有一个示例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tar cfz bin.tgz bin/*</span></span>
<span class="line"><span>          ^         ^</span></span>
<span class="line"><span>          |         +-- 将被包含的文件</span></span>
<span class="line"><span>          + 新的文件</span></span></code></pre></div><h3 id="zip" tabindex="-1">zip <a class="header-anchor" href="#zip" aria-label="Permalink to “zip”">​</a></h3><p><code>zip</code> 命令创建一个压缩文件，与此同时保留原始文件的完整性。语法像使用 <code>tar</code> 一样简单，只是你必需记住，你的原始文件名称应该是命令行上的最后一个参数。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ zip ./bigfile.zip bigfile</span></span>
<span class="line"><span>updating: bigfile (deflated 79%)</span></span>
<span class="line"><span>$ ls -l bigfile bigfile.zip</span></span>
<span class="line"><span>-rw-rw-r-- 1 shs shs 103270400 Apr 16 11:18 bigfile</span></span>
<span class="line"><span>-rw-rw-r-- 1 shs shs  21606889 Apr 16 11:19 bigfile.zip</span></span></code></pre></div><h3 id="gzip" tabindex="-1">gzip <a class="header-anchor" href="#gzip" aria-label="Permalink to “gzip”">​</a></h3><p><code>gzip</code> 命令非常容易使用。你只需要键入 <code>gzip</code>，紧随其后的是你想要压缩的文件名称。不像上述描述的命令，<code>gzip</code> 将“就地”“加密”文件。换句话说，原始文件将被“加密”文件替换。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gzip bigfile</span></span>
<span class="line"><span>$ ls -l bigfile*</span></span>
<span class="line"><span>-rw-rw-r-- 1 shs shs  21606751 Apr 15 17:57 bigfile.gz</span></span></code></pre></div><h3 id="bzip2" tabindex="-1">bzip2 <a class="header-anchor" href="#bzip2" aria-label="Permalink to “bzip2”">​</a></h3><p>像使用 <code>gzip</code> 命令一样，<code>bzip2</code> 将在你选择的文件“就地”压缩，不留下原始文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ bzip bigfile</span></span>
<span class="line"><span>$ ls -l bigfile*</span></span>
<span class="line"><span>-rw-rw-r-- 1 shs shs  18115234 Apr 15 17:57 bigfile.bz2</span></span></code></pre></div><h3 id="xz" tabindex="-1">xz <a class="header-anchor" href="#xz" aria-label="Permalink to “xz”">​</a></h3><p><code>xz</code> 是压缩命令团队中的一个相对较新的成员，在压缩文件的能力方面，它是一个领跑者。像先前的两个命令一样，你只需要将文件名称提供给命令。再强调一次，原始文件被就地压缩。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ xz bigfile</span></span>
<span class="line"><span>$ ls -l bigfile*</span></span>
<span class="line"><span>-rw-rw-r-- 1 shs shs 13427236 Apr 15 17:30 bigfile.xz</span></span></code></pre></div><p>对于大文件来说，你可能会注意到 <code>xz</code> 将比其它的压缩命令花费更多的运行时间，但是压缩的结果却是非常令人赞叹的。</p><h3 id="对比" tabindex="-1">对比 <a class="header-anchor" href="#对比" aria-label="Permalink to “对比”">​</a></h3><p>大多数人都听说过“大小不是一切”。所以，让我们比较一下文件大小以及一些当你计划如何压缩文件时的问题。</p><p>下面显示的统计数据都与压缩单个文件相关，在上面显示的示例中使用 <code>bigfile</code>。这个文件是一个大的且相当随机的文本文件。压缩率在一定程度上取决于文件的内容。</p><h4 id="大小减缩率" tabindex="-1">大小减缩率 <a class="header-anchor" href="#大小减缩率" aria-label="Permalink to “大小减缩率”">​</a></h4><p>当比较时，上面显示的各种压缩命产生下面的结果。百分比表示压缩文件与原始文件的比较效果。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>-rw-rw-r-- 1 shs shs 103270400 Apr 16 14:01 bigfile</span></span>
<span class="line"><span>------------------------------------------------------</span></span>
<span class="line"><span>-rw-rw-r-- 1 shs shs 18115234 Apr 16 13:59 bigfile.bz2    ~17%</span></span>
<span class="line"><span>-rw-rw-r-- 1 shs shs 21606751 Apr 16 14:00 bigfile.gz     ~21%</span></span>
<span class="line"><span>-rw-rw-r-- 1 shs shs 21608322 Apr 16 13:59 bigfile.tgz    ~21%</span></span>
<span class="line"><span>-rw-rw-r-- 1 shs shs 13427236 Apr 16 14:00 bigfile.xz     ~13%</span></span>
<span class="line"><span>-rw-rw-r-- 1 shs shs 21606889 Apr 16 13:59 bigfile.zip    ~21%</span></span></code></pre></div><p><code>xz</code> 命令获胜，最终只有压缩文件 13% 的大小，但是所有这些压缩命令都相当显著地减少原始文件的大小。</p><h4 id="是否替换原始文件" tabindex="-1">是否替换原始文件 <a class="header-anchor" href="#是否替换原始文件" aria-label="Permalink to “是否替换原始文件”">​</a></h4><p><code>bzip2</code>、<code>gzip</code> 和 <code>xz</code> 命令都用压缩文件替换原始文件。<code>tar</code> 和 <code>zip</code> 命令不替换。</p><h4 id="运行时间" tabindex="-1">运行时间 <a class="header-anchor" href="#运行时间" aria-label="Permalink to “运行时间”">​</a></h4><p><code>xz</code> 命令似乎比其它命令需要花费更多的时间来“加密”文件。对于 <code>bigfile</code> 来说，大概的时间是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>命令      运行时间</span></span>
<span class="line"><span>tar       4.9 秒</span></span>
<span class="line"><span>zip       5.2 秒</span></span>
<span class="line"><span>bzip2    22.8 秒</span></span>
<span class="line"><span>gzip      4.8 秒</span></span>
<span class="line"><span>xz       50.4 秒</span></span></code></pre></div><p>解压缩文件很可能比压缩时间要短得多。</p><h4 id="文件权限" tabindex="-1">文件权限 <a class="header-anchor" href="#文件权限" aria-label="Permalink to “文件权限”">​</a></h4><p>不管你对压缩文件设置什么权限，压缩文件的权限将基于你的 <code>umask</code> 设置，但 <code>bzip2</code> 除外，它保留了原始文件的权限。</p><h4 id="与-windows-的兼容性" tabindex="-1">与 Windows 的兼容性 <a class="header-anchor" href="#与-windows-的兼容性" aria-label="Permalink to “与 Windows 的兼容性”">​</a></h4><p><code>zip</code> 命令创建的文件可以在 Windows 系统以及 Linux 和其他 Unix 系统上使用（即解压），而无需安装其他工具，无论这些工具可能是可用还是不可用的。</p><h3 id="解压缩文件" tabindex="-1">解压缩文件 <a class="header-anchor" href="#解压缩文件" aria-label="Permalink to “解压缩文件”">​</a></h3><p>解压文件的命令与压缩文件的命令类似。在我们运行上述压缩命令后，这些命令用于解压缩 <code>bigfile</code>：</p><ul><li>tar： <code>tar xf bigfile.tgz</code></li><li>zip： <code>unzip bigfile.zip</code></li><li>gzip： <code>gunzip bigfile.gz</code></li><li>bzip2： <code>bunzip2 bigfile.gz2</code></li><li>xz： <code>xz -d bigfile.xz</code> 或 <code>unxz bigfile.xz</code></li></ul><h3 id="自己运行压缩对比" tabindex="-1">自己运行压缩对比 <a class="header-anchor" href="#自己运行压缩对比" aria-label="Permalink to “自己运行压缩对比”">​</a></h3><p>如果你想自己运行一些测试，抓取一个大的且可以替换的文件，并使用上面显示的每个命令来压缩它 —— 最好使用一个新的子目录。你可能需要先安装 <code>xz</code>，如果你想在测试中包含它的话。这个脚本可能更容易地进行压缩，但是可能需要花费几分钟完成。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 询问用户文件名称</span></span>
<span class="line"><span>echo -n &quot;filename&gt; &quot;</span></span>
<span class="line"><span>read filename</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 你需要这个，因为一些命令将替换原始文件</span></span>
<span class="line"><span>cp $filename $filename-2</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 先清理(以免先前的结果仍然可用)</span></span>
<span class="line"><span>rm $filename.*</span></span>
<span class="line"><span></span></span>
<span class="line"><span>tar cvfz ./$filename.tgz $filename &gt; /dev/null</span></span>
<span class="line"><span>zip $filename.zip $filename &gt; /dev/null</span></span>
<span class="line"><span>bzip2 $filename</span></span>
<span class="line"><span># 恢复原始文件</span></span>
<span class="line"><span>cp $filename-2 $filename</span></span>
<span class="line"><span>gzip $filename</span></span>
<span class="line"><span># 恢复原始文件</span></span>
<span class="line"><span>cp $filename-2 $filename</span></span>
<span class="line"><span>xz $filename</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 显示结果</span></span>
<span class="line"><span>ls -l $filename.*</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 替换原始文件</span></span>
<span class="line"><span>mv $filename-2 $filename</span></span></code></pre></div><hr>`,50)),p("p",null,[s[1]||(s[1]=a("via: ",-1)),e(n,{href:"https://www.networkworld.com/article/3538471/how-to-compress-files-on-linux-5-ways.html"},{default:i(()=>[...s[0]||(s[0]=[a("https://www.networkworld.com/article/3538471/how-to-compress-files-on-linux-5-ways.html",-1)])]),_:1})]),p("p",null,[s[6]||(s[6]=a("作者：",-1)),e(n,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:i(()=>[...s[2]||(s[2]=[a("Sandra Henry-Stocker",-1)])]),_:1}),s[7]||(s[7]=a(" 选题：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 译者：",-1)),e(n,{href:"https://github.com/robsean"},{default:i(()=>[...s[4]||(s[4]=[a("robsean",-1)])]),_:1}),s[9]||(s[9]=a(" 校对：",-1)),e(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),p("p",null,[s[12]||(s[12]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原创编译，",-1)),e(n,{href:"https://linux.cn/"},{default:i(()=>[...s[11]||(s[11]=[a("Linux中国",-1)])]),_:1}),s[14]||(s[14]=a(" 荣誉推出",-1))])])}const w=l(c,[["render",h]]);export{x as __pageData,w as default};
